#!/usr/bin/env bash
# Writes Version.xcconfig from Cargo.toml's [workspace.package] version, then runs xcodegen.
# CFBundleShortVersionString takes digits only, so 0.7.0-beta ships as 0.7.0 (build = CI run number).
set -euo pipefail
cd "$(dirname "$0")"
version=$(sed -n '/^\[workspace.package\]/,/^\[/s/^version = "\(.*\)"/\1/p' ../Cargo.toml)
cat > Version.xcconfig <<XC
// Generated by generate.sh from Cargo.toml ($version). Don't edit.
MARKETING_VERSION = ${version%%-*}
CURRENT_PROJECT_VERSION = ${GITHUB_RUN_NUMBER:-1}
XC
xcodegen generate --spec project.yml
